def is_nested(string):
    stack = []
    nested = False

    for char in string:
        if char == '[':
            stack.append(char)
            if len(stack) > 1:  # More than one opening bracket means nesting
                nested = True
        elif char == ']':
            if stack:
                stack.pop()
            else:
                return False  # Unmatched closing bracket

    return nested and not stack  # Must be nested and stack must be empty

